mapper.select:
select info.id as order_id, -- 必须：更新订单要用 info.customer_id, -- 必须：操作用户券要校验 bill.pay_amount, -- 必须：核销券时要传 bill.coupon_amount, -- 必须：判断是否已使用优惠券 cc.id as customer_coupon_id -- 必须：你缺的核心字段
from order_info info inner join order_bill bill on info.id = bill.order_id left join customer_coupon cc on info.id = cc.order_id
where info.customer_id = #{customerId} and info.order_no = #{orderNo}

select info.id, info.order_no, info.start_location, info.end_location,
if(info.status < 7, info.expect_amount, bill.pay_amount) as amount,
info.status, info.create_time from order_info info left join order_bill bill on info.id = bill.order_id where info.customer_id = #{customerId} and info.is_deleted =0 order by info.create_time desc
